mapper.select:
select upstream_job_code
from batch.job_dependency
where tenant_id = #{tenantId}
  and downstream_job_code = #{downstreamJobCode}
order by dependency_order

select upstream_job_code as "upstreamJobCode",
       biz_date_alignment as "bizDateAlignment"
from batch.job_dependency
where tenant_id = #{tenantId}
  and downstream_job_code = #{downstreamJobCode}
order by dependency_order

select calendar_code
from batch.job_definition
where tenant_id = #{tenantId}
  and job_code = #{jobCode}

select id
from batch.job_definition
where tenant_id = #{tenantId}
  and job_code = #{jobCode}
